'use strict';
const view=document.getElementById('view');
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=(small,big,desc)=>`<div class="eyebrow" style="color:var(--mint)">${small}</div><h2>${big}</h2><p class="subtitle">${desc}</p>`;
const table=(head,rows)=>`<div class="table-wrap"><table><thead><tr>${head.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const bullets=items=>`<ul>${items.map(x=>`<li>${esc(x).replace(/\[([^\]]+)\]\(([\w-]+\.md)\)/g,'<a href="#doc=$2">$1</a>')}</li>`).join('')}</ul>`;
const statusClass=s=>({'待開始':'idle','待討論確認':'review','進行中':'active','受阻':'blocked','待驗收':'review','已完成':'done'}[s]);
const badge=s=>`<span class="status-badge ${statusClass(s)}"><span aria-hidden="true"></span>${esc(s)}</span>`;
const currentUnit=()=>PLAN.find(t=>t.status!=='已完成')||PLAN[PLAN.length-1];
let unitStatus='全部',unitPhase='全部',lastRoute='';
const dailyUrl=(id,section='discussion')=>`#daily/${id}/${section}`;
const phaseNames=['研究','開發','測試'];
function roadmap(){
 view.innerHTML=title('PLAN OVERVIEW','原始計畫','目前優先：10/25 試繳、DataPack、v4.3 D-Plan 與首日繳交閉環。原始研究安排保留供後續執行。')+`<div class="overview-lead"><div><span class="small-label">兩週交付目標</span><h3>完整、可自主運作的參賽流程</h3><p>資料取得 → 決策與配置 → D-Plan → 提交回執 → 結算對帳。每個環節都能回測、追溯及恢復。</p></div><a class="primary-link" href="${dailyUrl(currentUnit().id)}">查看每日討論與進度 <span aria-hidden="true">↗</span></a></div><div class="plan-phases">${phaseNames.map((p,i)=>{const units=PLAN.filter(t=>t.phase===p);return `<section class="plan-phase phase-${i}"><span class="phase-number">0${i+1}</span><h3>${{研究:'前期準備',開發:'中期開發',測試:'後期測試'}[p]}</h3><p>${{研究:'盤點規則、名單、授權與可用資源，建立可驗證的起點。',開發:'先建立資料與帳本，再完成策略對照、Agent 工作流及提交對帳。',測試:'以樣本外、故障注入與完整彩排驗證，封存可重建的交付版本。'}[p]}</p><ol>${units.map(t=>`<li><a href="${dailyUrl(t.id)}"><span>${t.id}</span>${esc(t.title)}</a></li>`).join('')}</ol></section>`}).join('')}</div><div class="grid plan-policy"><section class="card"><div class="label">合作節奏</div><h3>每天 2–3 小時，依序驗收</h3><p>15–30 分鐘討論、30–90 分鐘配合、30–60 分鐘驗收。機器運算另計；未通過時延續當前單元，後續順延。</p></section><section class="card"><div class="label">技術取捨</div><h3>基線先行，增量才採用</h3><p>品質成長＋趨勢輪動起步。ML、LLM、JEV 依實測決定採用；優先本地模型，付費 API 未預授權。RL／時序研究可裁切。</p></section></div><div class="note">正式交付須保留帳本、合規、證據鏈、提交、回測與恢復驗收。U12 啟動連續 72 小時 soak，U14 以實際測試時數驗收。</div><div class="page-links"><a class="link-button" href="#doc=README.md">計畫說明</a><a class="link-button" href="#strategy">策略與模型研究</a><a class="link-button" href="#gates">規則與驗收</a></div>`;
}
function daily(id=currentUnit().id,section='discussion'){
 const t=PLAN.find(x=>x.id===id)||currentUnit();
 if(!['discussion','reply','evidence','dependencies'].includes(section))section='discussion';
 const counts=Object.fromEntries(['已完成','進行中','待驗收','受阻'].map(s=>[s,PLAN.filter(t=>t.status===s).length]));
 const next={'待開始':'先討論並確認本單元清單；前置單元驗收後才開發。','待討論確認':'確認討論結果與當日清單後，才能開始執行。','進行中':'完成已確認的任務，記錄驗證結果與失敗案例。','受阻':'先處理阻礙與外部依賴，再恢復已授權工作。','待驗收':'檢視驗證證據與未解項目，等待你的驗收確認。','已完成':'本單元已確認驗收，可進入下一單元的討論。'}[t.status];
 view.innerHTML=`<div class="execution-heading"><div><div class="eyebrow">DAILY WORKSPACE</div><h2>每日討論與進度</h2><p class="subtitle">14 個工作單元，按確認、執行與驗收推進。</p></div><a class="link-button" href="#roadmap">查看原始計畫</a></div><div class="progress-strip" aria-label="整體進度"><div class="completion"><strong>${counts['已完成']}<small> / 14 已完成</small></strong><progress max="14" value="${counts['已完成']}" aria-label="驗收完成進度"></progress></div>${['進行中','待驗收','受阻'].map(s=>`<div><span>${s}</span><strong>${counts[s]}</strong></div>`).join('')}<a href="${dailyUrl(currentUnit().id)}">目前單元 ${currentUnit().id} <span aria-hidden="true">→</span></a></div><div class="execution-workspace"><section class="unit-navigation" aria-label="選擇工作單元"><div class="unit-nav-title"><strong>工作單元</strong><span>依序驗收</span></div><div class="unit-filters"><label>階段<select id="unit-phase">${['全部',...phaseNames].map(s=>`<option ${s===unitPhase?'selected':''}>${s}</option>`).join('')}</select></label><label>狀態<select id="unit-status">${['全部','待開始','待討論確認','進行中','受阻','待驗收','已完成'].map(s=>`<option ${s===unitStatus?'selected':''}>${s}</option>`).join('')}</select></label></div><div id="unit-list" class="unit-list"></div><div class="mobile-unit"><label for="unit-picker">選擇單元</label><select id="unit-picker">${PLAN.map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.id} ${esc(x.title)} · ${x.status}</option>`).join('')}</select></div><p class="unit-nav-foot">狀態由每日 TODO 同步。<br>尚未驗收的單元不算完成。</p></section><article class="execution-detail"><div class="unit-heading"><div><div class="unit-kicker">${t.id} <span>／ ${t.phase}</span></div><h3>${esc(t.title)}</h3></div>${badge(t.status)}</div><p class="next-action"><strong>下一步</strong>${next}</p><div class="confirmation-row"><div><span>清單確認</span><strong>${t.list_confirmed==='未確認'?'尚未確認':'已確認'}</strong><small>${esc(t.list_confirmed)}</small></div><div><span>驗收確認</span><strong>${t.acceptance_confirmed==='未確認'?'尚未確認':'已確認'}</strong><small>${esc(t.acceptance_confirmed)}</small></div></div><div class="unit-tabs" role="tablist" aria-label="單元內容">${[['discussion','討論與任務'],['reply','準備與回覆'],['evidence','驗收與證據'],['dependencies','依賴與阻礙']].map(([key,label])=>`<button role="tab" id="tab-${key}" aria-controls="unit-panel" aria-selected="${section===key}" tabindex="${section===key?0:-1}" data-section="${key}">${label}</button>`).join('')}</div><div class="unit-panel" id="unit-panel" role="tabpanel" aria-labelledby="tab-${section}" tabindex="0">${unitPanel(t,section)}</div><div class="unit-footer"><a href="#doc=DAILY_TODO.md">閱讀完整每日 TODO</a><div>${t.day>1?`<a href="${dailyUrl(PLAN[t.day-2].id)}">← 上一單元</a>`:''}${t.day<14?`<a href="${dailyUrl(PLAN[t.day].id)}">下一單元 →</a>`:''}</div></div></article></div>`;
 renderUnitList(t.id);
 if(section==='reply')bindReplyForm(t);
 document.getElementById('unit-phase').onchange=e=>{unitPhase=e.target.value;renderUnitList(t.id)};
 document.getElementById('unit-status').onchange=e=>{unitStatus=e.target.value;renderUnitList(t.id)};
 document.getElementById('unit-picker').onchange=e=>{location.hash=dailyUrl(e.target.value)};
 view.querySelectorAll('[data-section]').forEach(b=>{
  b.onclick=()=>{location.hash=dailyUrl(t.id,b.dataset.section)};
  b.onkeydown=e=>{const keys=['discussion','reply','evidence','dependencies'];let i=keys.indexOf(b.dataset.section);if(e.key==='ArrowRight')i=(i+1)%keys.length;else if(e.key==='ArrowLeft')i=(i+keys.length-1)%keys.length;else if(e.key==='Home')i=0;else if(e.key==='End')i=keys.length-1;else return;e.preventDefault();location.hash=dailyUrl(t.id,keys[i]);};
 });
}
function renderUnitList(selected){
 const units=PLAN.filter(t=>(unitPhase==='全部'||t.phase===unitPhase)&&(unitStatus==='全部'||t.status===unitStatus));
 document.getElementById('unit-list').innerHTML=units.length?units.map(t=>`<a class="unit-item ${selected===t.id?'selected':''}" href="${dailyUrl(t.id)}" ${selected===t.id?'aria-current="step"':''}><span class="unit-id">${t.id}</span><div><strong>${esc(t.title)}</strong><span class="unit-meta">${t.phase} ${badge(t.status)}</span></div></a>`).join(''):`<div class="empty-units"><strong>沒有符合的單元</strong><p>目前沒有${unitStatus==='全部'?'此階段':unitStatus}的工作單元。</p><button id="clear-unit-filters" class="quiet">清除篩選</button></div>`;
 const reset=document.getElementById('clear-unit-filters');if(reset)reset.onclick=()=>{unitPhase='全部';unitStatus='全部';document.getElementById('unit-phase').value='全部';document.getElementById('unit-status').value='全部';renderUnitList(selected)};
}
function unitPanel(t,section){
 if(section==='reply')return replyPanel(t);
 if(section==='discussion')return `<section class="discussion-focus"><div class="panel-label">當日討論</div><h4>這個單元要釐清什麼？</h4>${bullets(t.discussion)}</section><div class="task-columns"><section class="task-card"><div class="panel-label">你 · 討論與配合</div><h4>需要你的投入</h4>${bullets(t.human)}</section><section class="task-card"><div class="panel-label">Codex · 開發與驗證</div><h4>我負責的工作</h4>${bullets(t.codex)}</section></div><section class="compute-tasks"><h4>機器運算與測試</h4>${bullets(t.machine)}</section><div class="panel-footnote">討論 15–30 分鐘 · 配合 30–90 分鐘 · 驗收 30–60 分鐘。尚未執行的內容屬計畫，不代表已有結果。</div><a class="link-button prepare-cta" href="${dailyUrl(t.id,'reply')}">查看你需準備的材料並填寫回覆 →</a>`;
 if(section==='evidence')return `<section class="acceptance-panel"><div class="panel-label">驗收標準</div><h4>達到什麼條件才算通過？</h4>${bullets(t.acceptance)}</section><section class="evidence-panel"><div class="panel-label">驗證紀錄</div><h4>可檢視的證據</h4>${bullets(t.evidence)}</section><div class="panel-footnote">Codex 記錄驗證結果；你確認驗收後才標為已完成。mock 或接口連通不等於正式流程驗證。</div>`;
 return `<section><div class="panel-label">前置依賴</div><h4>開始前要先完成</h4>${t.deps.length?`<div class="dependency-list">${t.deps.map(id=>{const x=PLAN.find(x=>x.id===id);return `<a href="${dailyUrl(id)}"><div><span>${id}</span><strong>${esc(x.title)}</strong></div>${badge(x.status)}<span aria-hidden="true">↗</span></a>`}).join('')}</div>`:'<p class="no-dependency">這是起點，沒有前置單元。</p>'}</section><section class="blocker-panel"><div class="panel-label">阻礙與外部依賴</div><h4>尚需處理的事項</h4>${bullets(t.blockers)}</section><div class="panel-footnote">先解決阻礙，再確認是否能繼續；不以日期到期自動跳過驗收。</div>`;
}
function strategy(){view.innerHTML=title('STRATEGY & MODEL RESEARCH','本輪採可驗證的規則基線','營收成長、估值與流動性規則已產生本地候選；ML、LLM、JEV 留作後續驗證研究。')+`<div class="pipeline"><span>PIT 資料</span><span>因子／ML 排序</span><span>LLM＋JEV 判斷</span><span>限制配置</span><span>D-Plan 驗證</span></div><div class="grid"><div class="card"><div class="label">正式主候選</div><h3>品質成長 × 趨勢輪動</h3><p>營收、獲利品質、價格趨勢及法人籌碼，從官方 150 檔中形成候選。初始設計 25 檔，成本與換手納入比較。</p></div><div class="card"><div class="label">明確的採用順序</div><h3>基線先行，增量才升級</h3><p>ML 不勝出就保留多因子；JEV 沒通過中文金融驗收就留在影子模式。RL／TSFM 合計最多 3 小時可選研究。</p></div></div><div class="select-row"><label for="model">查看研究方案</label><select id="model"><option value="ml">ML／數學配置</option><option value="jev">JEV-27B／TypeSafe Jev</option><option value="llm">LLM 事件與證據鏈</option><option value="rl">RL／時序模型支線</option></select></div><article id="model-detail" class="card"></article><div class="note warning">模型的選項機率 ≠ 股票上漲機率。型別正確不保證語意正確；硬規則永遠由程式驗證。</div><a class="link-button" href="#doc=03-strategies.md">閱讀完整策略與實驗設計</a>`;document.getElementById('model').onchange=model;model()}
function model(){const key=document.getElementById('model').value;const content={ml:['LightGBM 排序＋受限制配置','U07 · 對照候選','以交易日作群組，預測 5／10／20 日可成交超額報酬。比較相同樣本外切分下的淨值、回撤、換手與各折增量。配置加入風險與交易成本，整張取整後再次檢查所有限制。','採用：多數驗證折成本後增量為正；未改善則退回 E01 基線。'],jev:['兩個 JEV，分開評測','U08 · 有限研究','AutoTrust JEV-27B 是獨立開放權重模型；TypeSafe Jev 是原廠託管決策服務。先測 200 則中文金融案例，涵蓋否定、矛盾、缺證據和選項亂序。本地模型優先，JEV 適配最多一個開發工作日；付費 API 尚未授權。','建議門檻：macro-F1 ≥0.85，高信心錯判≤5%，亂序一致率≥95%；均待實測。<br><a href="https://huggingface.co/autotrust/JEV-27B" target="_blank" rel="noopener">AutoTrust 模型卡</a> · <a href="https://docs.typesafe.ai/introduction/quickstart" target="_blank" rel="noopener">TypeSafe 官方文件</a>'],llm:['讓每筆決策都有來源','U08–U09 · 核心能力','來源→事實→推論→決策→委託，形成可追溯的完整鏈。抽取事件與相反證據，先比格式、數字和引用正確率，再評估事件特徵是否帶來策略增量。','採用：能回源、時間正確；不能替人工挑選的股票事後編理由。'],rl:['策略混合與風險預測','可裁切研究','RL 只在既有策略配比／風險檔位中選擇，不自由生成個股委託；Chronos-2／TimesFM 可測量能與波動。沒有餘裕就交付假說和接口，停止訓練。','採用：超越固定混合／naive／EWMA，且通過相同交易與資料洩漏檢查。TimesFM 3.0 自架授權另核實。']};const [h,t,p,g]=content[key];document.getElementById('model-detail').innerHTML=`<span class="tag">${t}</span><h3>${h}</h3><p>${p}</p><div class="note">${g}</div>`}
function gates(){view.innerHTML=title('RULES & ACCEPTANCE','先保資格，再優化淨值','初賽以期末 NAV 排名；同 NAV 時才比較 MDD。數值限制、自主性與提交成功缺一不可。')+`<div class="grid"><div class="card fact"><strong>22 / 24</strong><p>至少成功提交的交易日數；目標全勤。</p></div><div class="card fact"><strong>08:55</strong><p>官方截止；內部 08:10 首送、08:30 確認回執。</p></div></div>`+table(['官方限制','系統處理'],[['150 檔白名單、持股 20–30 檔','官方固定清單；取整和例外成交後重算。'],['2330 ≤25%；其餘 ≤10%','內部建議 20%／8%，留價格波動緩衝。'],['現金 0–25%','計費稅；測買價、賣價和收盤相對變動。'],['整張 1,000 股，禁止放空／當沖','按官方公式推導；與實際庫存對帳防超賣。'],['Active Share 不得連續兩日低於 15%','逐一比較指定 ETF；口徑待確認，內部目標 ≥20%。'],['累計三次警告取消資格','每日警告和成功日計數；無效日不能假設成交。']])+`<h3>四個驗收關卡</h3>${[['U01–U06','資料與規則','150 檔、可用時間、費稅、首日建倉基線。'],['U09–U10','完整自主流程','snapshot 到 D-Plan；模型決策可查證，可從 checkpoint 恢復。'],['U11','候選凍結與 OOS','切分、消融、24 日短窗；不反覆看 holdout 調參。'],['U14','可參賽交接','72 小時 soak、30 日數值回放、至少 10 日完整 Agent 鏈；未驗證項明列。']].map(r=>`<details><summary>${r[0]} · ${r[1]}</summary><p>${r[2]}</p></details>`).join('')}<div class="note warning">待主辦方確認：Active Share 前 15 大計算口徑、無成交價例外、提交／庫存接口、比賽中模型改版邊界。</div><a class="link-button" href="#doc=01-rules.md">規則來源與差異</a> <a class="link-button" href="#doc=06-validation.md">完整測試方案</a>`}
function resources(){view.innerHTML=title('DATA & COMPUTE','讓資源服務兩週的關鍵路徑','優先接通可追溯資料與日常推論，不為了用滿 GPU 而訓練不必要的模型。')+table(['資源','分工','主要限制'],[['M3 Ultra · 512GB','資料倉庫、CPU 回測、開發與離線模型對照','自訂 JEV head 的 MLX／MPS 支援需實測。'],['RTX A6000 · 常見 48GB','CUDA 主實驗、時序模型、量化 JEV 候選','27B BF16 純權重約 54GB，單卡不足。'],['RTX 3090 · 常見 24GB','小模型、事件批次、RL seeds','4-bit 仍要留 KV／adapter／activation 空間。'],['RTX A5000 · 常見 24GB','影子服務、備援與故障演練','正式晨間資源不被研究任務搶占。']])+`<div class="grid"><div class="card"><div class="label">PIT DATA</div><h3>TEJ PRO＋官方行情</h3><p>先確認 API 權限、財報首發／重編資料和歷史深度。原始價負責結算，調整價僅供研究。</p></div><div class="card"><div class="label">PROVENANCE</div><h3>新聞 API＋台美股 MCP</h3><p>保留原始來源、時間、單位和快照。MCP 是通道，不代表底層資料已經核實。</p></div></div><div class="note">U01 實測目前工作環境 M4 Pro 24GiB；M3 與 NVIDIA 尚待接通。常見顯存容量仍需實查；不同機器記憶體不能直接相加。JEV API 存取、價格、量化相容與中文校準皆未實測。</div><a class="link-button" href="#doc=05-data-compute.md">查看資料契約與部署預案</a>`}
function documents(id){
 const executionIds=['18-candidate-implementation.md','19-trading-risk-gate.md','20-etf-source-readiness.md','17-competition-readiness.md','DAILY_TODO.md','U01_REPORT.md','02-roadmap.md'];
 if(!id){view.innerHTML=title('DOCUMENT LIBRARY','文件中心','原始規劃與每日執行紀錄分開閱讀。')+`<section class="library-group"><div class="library-heading"><h3>每日執行與驗證</h3><a href="#daily">前往每日工作台 →</a></div><div class="document-list">${DOCS.filter(d=>executionIds.includes(d.id)).map(documentCard).join('')}</div></section><section class="library-group"><div class="library-heading"><h3>原始計畫與研究</h3><a href="#roadmap">查看原始計畫 →</a></div><div class="document-list">${DOCS.filter(d=>!executionIds.includes(d.id)).map(documentCard).join('')}</div></section>`;return}
 const d=DOCS.find(x=>x.id===id)||DOCS.find(x=>x.id==='README.md');const dailyDocument=executionIds.includes(d.id);
 view.innerHTML=`<div class="section-top"><div><a href="${dailyDocument?'#daily':'#roadmap'}">← ${dailyDocument?'每日討論與進度':'原始計畫'}</a><a class="reader-all" href="#documents">全部文件</a></div><a class="link-button" href="documents/${encodeURIComponent(d.id)}" download>下載 Markdown</a></div><div class="note">本地來源位於專案 docs/，未將原始競賽文件或付費資料上傳網站；各條款附文件名與頁碼。</div><article class="reader">${d.html}</article>`;
 view.querySelectorAll('a[href^="https:"]').forEach(a=>{a.target='_blank';a.rel='noopener'});
}
function documentCard(d){return `<a href="#doc=${encodeURIComponent(d.id)}">${esc(d.title)}<small>${esc(d.id)}</small><span class="document-open">閱讀文件 ↗</span></a>`}
function route(){
 let hash;try{hash=decodeURIComponent(location.hash.slice(1))}catch{hash='daily'}
 hash=hash||'daily';const parts=hash.split('/');let v=hash.startsWith('doc=')?'documents':parts[0];
 if(!['daily','roadmap','strategy','gates','resources','documents','data','apis'].includes(v))v='daily';
 const previous=document.activeElement?.dataset?.section;
 document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.view===v);if(a.dataset.view===v)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 if(v==='documents')documents(hash.startsWith('doc=')?hash.slice(4):null);
 else if(v==='daily')daily(parts[1],parts[2]);
 else({roadmap,strategy,gates,resources,data:decisionData,apis:exchangeApis})[v]();
 if(v==='daily'&&previous)view.querySelector('[role="tab"][aria-selected="true"]')?.focus();
 const routeKey=v==='daily'?`daily/${parts[1]||currentUnit().id}`:hash;
 if(lastRoute&&lastRoute!==routeKey)window.scrollTo({top:0,behavior:'auto'});
 lastRoute=routeKey;
 document.title=`玉山 AI Agent｜${{daily:'每日討論與進度',roadmap:'原始計畫',strategy:'策略與 JEV',gates:'規則與驗收',resources:'資料與算力',documents:'文件中心',data:'決策資料地圖',apis:'官方 API 端點'}[v]}`;
}
window.addEventListener('hashchange',route);document.getElementById('print').onclick=()=>window.print();route();
